'use strict';
const PUSH_COPY_EN={urgent:['Urgent item request','Only requests explicitly marked urgent by the sender.'],shopping:['Shopping requests','Normal direct requests, plus unfinished requests at your chosen time.'],attendance:['Attendance','Only when your own dinner attendance is still pending.'],prep:['Dinner preparation','Uncooked dinner: check tasks and portions, not a last-minute thawing instruction.'],expiry:['Entered expiry dates','Check pantry items with an entered expiry today or tomorrow.'],receipt:['Receipt reminder','Purchased today but no receipt has been saved for today.'],budget:['Weekly budget','Once per week when recorded spending exceeds your target.'],weekly:['Plan the next week','Sunday around 18:00 Sydney time.']};
const DEFAULT_PUSH_TYPES=['urgent','shopping','expiry','weekly'];
async function pushSettings(){await refreshPushStatus();const profile=pushProfile(),id=pushDeviceId(),supported='Notification'in window&&'PushManager'in window&&'serviceWorker'in navigator,permission='Notification'in window?Notification.permission:'unsupported';modal(tr('Push & người nhận','Push & recipients'),`<p>${tr('Netlify gửi nhắc tự động theo dữ liệu đã đồng bộ. Yêu cầu mua do thành viên bấm gửi, chỉ tới người được chọn. Mỗi điện thoại cần đăng ký riêng.','Netlify sends automatic reminders using synced family data. A family member sends direct requests to selected recipients. Each phone must register separately.')}</p><div class="status-line"><span>${tr('Thiết bị này','This device')}</span><b>${esc(permission)}</b></div><div class="status-line"><span>Netlify</span><b>${cloudConnection.connected?tr('Đã kết nối','Connected'):tr('Chưa kết nối','Disconnected')}</b></div>${!cloudConnection.available?`<p class="callout">${tr('Bản xem thử cục bộ không gửi push. Cần website Netlify HTTPS đã cấu hình FAMILY_PASSWORD và kết nối dữ liệu chung.','This local preview cannot send push. Use the HTTPS Netlify site with FAMILY_PASSWORD configured and family storage connected.')}</p>`:''}<form id="push-device-form"><div class="form-grid"><div class="field"><label for="push-member">${tr('Điện thoại của ai?','Who uses this phone?')}</label><select id="push-member">${state.members.map(m=>`<option value="${m.id}" ${profile.memberId===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></div><div class="field"><label for="push-label">${tr('Tên thiết bị','Device name')}</label><input id="push-label" maxlength="80" value="${esc(profile.label||tr('Điện thoại của tôi','My phone'))}"></div><div class="field"><label for="push-role">${tr('Vai trò','Role')}</label><select id="push-role">${[['both',tr('Nấu ăn & đi chợ','Cook & shopper')],['cook',tr('Chủ yếu nấu ăn','Mostly cooking')],['shopper',tr('Chủ yếu đi chợ','Mostly shopping')]].map(([v,n])=>`<option value="${v}" ${(profile.role||'both')===v?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label for="push-language">${tr('Ngôn ngữ thông báo','Notification language')}</label><select id="push-language"><option value="vi" ${(profile.language||appLanguage)==='vi'?'selected':''}>Tiếng Việt</option><option value="en" ${(profile.language||appLanguage)==='en'?'selected':''}>English</option></select></div></div><h3>${tr('Những việc muốn nhận','Choose reminders')}</h3><div class="push-type-list">${Object.entries(PUSH_LABELS).map(([key,[name,note]])=>`<label class="checked-label"><input class="check push-type" type="checkbox" value="${key}" ${(profile.types?.[key]??DEFAULT_PUSH_TYPES.includes(key))?'checked':''}><span>${appLanguage==='en'?PUSH_COPY_EN[key][0]:name}<small style="display:block">${appLanguage==='en'?PUSH_COPY_EN[key][1]:note}</small></span></label>`).join('')}</div><div class="form-grid topspace"><div class="field"><label for="push-quiet-start">${tr('Yên lặng từ','Quiet hours from')}</label><input id="push-quiet-start" type="time" required value="${profile.quietStart||'21:00'}"></div><div class="field"><label for="push-quiet-end">${tr('Đến','Until')}</label><input id="push-quiet-end" type="time" required value="${profile.quietEnd||'07:00'}"></div></div><label class="checked-label"><input id="push-urgent-bypass" class="check" type="checkbox" ${profile.urgentBypass?'checked':''}>${tr('Cho phép yêu cầu khẩn đi qua giờ yên lặng','Allow explicitly urgent requests during quiet hours')}</label></form><div class="callout">${tr('Tối đa 2 nhắc tự động/ngày/thiết bị. Vai trò lọc nhắc tự động: người nấu nhận sơ chế/hạn dùng/thực đơn; người mua nhận mua đồ/hóa đơn/ngân sách. Báo cơm chỉ tới người chưa báo. Yêu cầu trực tiếp theo người nhận bạn chọn, tôn trọng các mục đã bật và giờ yên lặng.','Up to 2 automatic reminders per device per day. Roles filter automated reminders: cooks get prep/expiry/menu; shoppers get shopping/receipt/budget. Attendance goes only to pending members. Direct requests follow selected recipients, their enabled types and quiet hours.')}</div><details class="simple-disclosure"><summary>${tr('Giờ nhắc chung của gia đình','Family reminder times')}</summary><form id="push-times-form"><div class="form-grid">${[['attendanceTime',tr('Báo cơm','Attendance'),'10:30'],['prepReminderTime',tr('Kiểm tra sơ chế','Review prep'),'17:00'],['shoppingReminderTime',tr('Nhắc yêu cầu mua','Unfinished requests'),'09:00']].map(([key,label,time])=>`<div class="field"><label>${label}</label><input type="time" name="${key}" required value="${state.preferences[key]||time}"></div>`).join('')}</div><button class="btn" type="submit">${tr('Lưu giờ chung','Save family times')}</button></form></details><h3>${tr('Thiết bị đã đăng ký','Registered devices')}</h3>${pushStatusCache.devices.map(d=>`<div class="push-device-row" data-user-content>${esc(d.label)} · ${esc(state.members.find(m=>m.id===d.memberId)?.name||d.memberId)}${d.deviceId===id?' · '+tr('Thiết bị này','This device'):''}</div>`).join('')||`<p>${tr('Chưa có thiết bị nhận.','No recipient devices registered.')}</p>`}<p class="hint">${tr('iPhone: thêm ra Màn hình chính, mở từ biểu tượng rồi bật push. Android: website HTTPS và trình duyệt hỗ trợ Web Push. Lịch theo Sydney, có giờ mùa hè, kiểm tra 15 phút/lần. Máy tắt mạng/Focus có thể nhận muộn hoặc không hiện chuông. Thông báo bị bỏ qua do yên lặng/giới hạn không được gửi bù; việc cần làm vẫn ở trong app.','iPhone: install to Home Screen and open from its icon before enabling push. Android: use HTTPS and a Web Push browser. Schedules use Sydney time with daylight saving and check every 15 minutes. Offline/Focus settings may delay or silence delivery. Quiet-hour or capped reminders are not queued for later; tasks remain in the app.')}</p>`,`<button class="btn" data-feature="cloud-settings">${tr('Kết nối Netlify','Connect Netlify')}</button>${pushStatusCache.devices.some(d=>d.deviceId===id)?`<button class="btn" data-push-action="unsubscribe">${tr('Tắt thiết bị này','Turn off this device')}</button>`:''}<button class="btn" data-push-action="test" ${!cloudConnection.connected?'disabled':''}>${tr('Thử thiết bị này','Test this device')}</button><button class="btn primary" data-push-action="subscribe" ${!supported||!cloudConnection.connected?'disabled':''}>${tr('Bật / lưu nhận push','Enable / save push')}</button>`,true)}
remindersModal=pushSettings;
